using System.Collections.ObjectModel; using System.Diagnostics; using System.Windows; using System.Windows.Controls; using DvrkTweaks.Data; using DvrkTweaks.Models; using DvrkTweaks.Services;
namespace DvrkTweaks;
public partial class MainWindow:Window{readonly TweakService service=new();readonly ObservableCollection<Tweak> visible=new();string category="FPS & Graphics";public MainWindow(){InitializeComponent();TweaksList.ItemsSource=visible;AdminText.Text="ADMIN: "+(service.IsAdministrator()?"YES":"NO");BuildNav();SelectCategory(category);}static string Icon(string c)=>c switch{"FPS & Graphics"=>"🎮","Input & Mouse"=>"🖱","Network & Ping"=>"🌐","Windows Latency"=>"⚡","Fortnite"=>"🎯","GPU & Driver"=>"🖥","Background & Storage"=>"💾","Power & CPU"=>"🚀","Privacy & Services"=>"🛡",_=>"•"};void BuildNav(){NavPanel.Children.Clear();foreach(var c in TweakCatalog.All.Select(x=>x.Category).Distinct()){var b=new Button{Content=$"{Icon(c)}  {c}",Tag=c,Style=(Style)FindResource("Nav")};b.Click+=(_,_)=>SelectCategory((string)b.Tag);NavPanel.Children.Add(b);}}void SelectCategory(string c){category=c;TitleText.Text=c;SubtitleText.Text=$"{TweakCatalog.All.Count(x=>x.Category==c)} performance switches • FPS / ping / input / latency";SearchBox.Text="";Refresh();}void Refresh(){visible.Clear();var q=SearchBox.Text.Trim();foreach(var t in TweakCatalog.All.Where(x=>x.Category==category&&(q==""||x.Name.Contains(q,StringComparison.OrdinalIgnoreCase))))visible.Add(t);SwitchCount.Text=visible.Count.ToString();EnabledCount.Text=visible.Count(x=>x.IsEnabled).ToString();}void SearchBox_TextChanged(object s,TextChangedEventArgs e){if(IsInitialized)Refresh();}void Tweak_Checked(object s,RoutedEventArgs e){if(s is CheckBox c&&c.DataContext is Tweak t)Apply(t,true);}void Tweak_Unchecked(object s,RoutedEventArgs e){if(s is CheckBox c&&c.DataContext is Tweak t)Apply(t,false);}void Apply(Tweak t,bool on){try{service.Apply(t.ActionKey,on);StatusText.Text=on?"APPLIED":"RESTORED";Refresh();}catch(Exception ex){t.IsEnabled=!on;MessageBox.Show(ex.Message,"DVRK Tweaks");Refresh();}}void ApplyAll_Click(object s,RoutedEventArgs e){foreach(var t in TweakCatalog.All.Where(x=>x.IsEnabled))try{service.Apply(t.ActionKey,true);}catch{}StatusText.Text="APPLIED";Refresh();}void Reset_Click(object s,RoutedEventArgs e){foreach(var t in TweakCatalog.All){try{service.Apply(t.ActionKey,false);}catch{}t.IsEnabled=false;}StatusText.Text="RESTORED";Refresh();}void Discord_Click(object s,RoutedEventArgs e){Process.Start(new ProcessStartInfo("https://discord.gg/sYAFfpemb"){UseShellExecute=true});}}
